// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Uint64 } from '@stdlib/types/number';
import { Collection, NumericArray } from '@stdlib/types/array';

/**
* Interface for testing whether two 64-bit unsigned integers are equal.
*/
interface IsEqual {
	/**
	* Tests whether two 64-bit unsigned integers are equal.
	*
	* @param a - first 64-bit unsigned integer
	* @param b - second 64-bit unsigned integer
	* @returns boolean indicating if both 64-bit unsigned integers are equal
	*
	* @example
	* var Uint64 = require( '@stdlib/number/uint64/ctor' );
	*
	* var a = new Uint64( 1234 );
	* var b = Uint64.of( 0, 1234 );
	*
	* var v = isEqual( a, b );
	* // returns true
	*/
	( a: Uint64, b: Uint64 ): boolean;

	/**
	* Tests whether two 64-bit unsigned integers are equal using word comparison.
	*
	* @param ah - high 32-bit word of the first 64-bit unsigned integer
	* @param al - low 32-bit word of the first 64-bit unsigned integer
	* @param bh - high 32-bit word of the second 64-bit unsigned integer
	* @param bl - low 32-bit word of the second 64-bit unsigned integer
	* @returns boolean indicating if both 64-bit unsigned integers are equal
	*
	* @example
	* var v = isEqual.words( 0, 5, 0, 5 );
	* // returns true
	*
	* var v = isEqual.words( 0, 5, 0, 10 );
	* // returns false
	*/
	words( ah: number, al: number, bh: number, bl: number ): boolean;

	/**
	* Tests whether two 64-bit unsigned integers stored in integer-valued strided array views are equal.
	*
	* @param a - first 64-bit unsigned integer strided array view containing interleaved 32-bit unsigned integer high and low order words
	* @param strideA - stride length for `a`
	* @param offsetA - starting index for `a`
	* @param b - second 64-bit unsigned integer strided array view containing interleaved 32-bit unsigned integer high and low order words
	* @param strideB - stride length for `b`
	* @param offsetB - starting index for `b`
	* @returns boolean indicating if both 64-bit unsigned integers are equal
	*
	* @example
	* var Uint32Array = require( '@stdlib/array/uint32' );
	*
	* var a = new Uint32Array( [ 0, 5 ] );
	* var b = new Uint32Array( [ 0, 5 ] );
	*
	* var v = isEqual.strided( a, 1, 0, b, 1, 0 );
	* // returns true
	*/
	strided<T extends NumericArray | Collection<number>, U extends NumericArray | Collection<number>>( a: T, strideA: number, offsetA: number, b: U, strideB: number, offsetB: number ): boolean;
}

/**
* Tests whether two 64-bit unsigned integers are equal.
*
* @param a - first 64-bit unsigned integer
* @param b - second 64-bit unsigned integer
* @returns boolean indicating if both 64-bit unsigned integers are equal
*
* @example
* var Uint64 = require( '@stdlib/number/uint64/ctor' );
*
* var a = new Uint64( 1234 );
* var b = Uint64.of( 0, 1234 );
*
* var v = isEqual( a, b );
* // returns true
*
* @example
* var v = isEqual.words( 0, 5, 0, 5 );
* // returns true
*
* @example
* var Uint32Array = require( '@stdlib/array/uint32' );
*
* var a = new Uint32Array( [ 0, 5 ] );
* var b = new Uint32Array( [ 0, 5 ] );
*
* var v = isEqual.strided( a, 1, 0, b, 1, 0 );
* // returns true
*/
declare var isEqual: IsEqual;


// EXPORTS //

export = isEqual;
